use core::ffi::{c_void,c_int}; unsafe extern "C" {fn memcmp(a:*const c_void,b:*const c_void,n:usize)->c_int;}
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NIZ_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NIZ_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NIZ_KMX::KMX_realloc)]
#[kani::proof]
fn certificate(){let a:u8=kani::any();let b:u8=kani::any();let before_a=a;let before_b=b;let reply=unsafe{memcmp((&a as *const u8).cast(),(&b as *const u8).cast(),1)};assert!((reply==0)==(a==b));assert!(a==before_a);assert!(b==before_b);}
